public class Shop {
    private int stock = 0;

    public void restock(int amount) {
        synchronized(this) {
            stock += amount;
        }
    }
}

class Counter {
    private int count = 0;
    public void increment() {
        for (int i = 0; i < 1000; i++) {
            count++;
        }
    }
    public int getCount() { return count; }
}

